<?php require_once 'config/config.php';require_login();$no=$_GET['id']??'';$s=$pdo->prepare("SELECT s.*,c.name customer,u.full_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.user_id WHERE s.receipt_no=?");$s->execute([$no]);$sale=$s->fetch();if(!$sale)die('Receipt not found');$it=$pdo->prepare("SELECT * FROM sale_items WHERE sale_id=?");$it->execute([$sale['id']]);$items=$it->fetchAll();$set=$pdo->query("SELECT * FROM settings WHERE id=1")->fetch();?>
<!doctype html><html><head><meta charset="utf-8"><title><?=e($sale['receipt_no'])?></title><style>body{font-family:Arial;width:80mm;margin:auto;font-size:12px}.center{text-align:center}table{width:100%;border-collapse:collapse}td{padding:4px 0;border-bottom:1px dotted #aaa}.right{text-align:right}.total{font-size:16px;font-weight:bold}@media print{button{display:none}}</style></head><body>
<div class="center"><h2><?=e($set['business_name'])?></h2><div><?=e($set['phone'])?></div><div><?=e($set['email'])?></div><hr><b>RECEIPT <?=e($sale['receipt_no'])?></b><br><?=e($sale['created_at'])?></div>
<p>Customer: <?=e($sale['customer']??'Walk-in')?><br>Served by: <?=e($sale['full_name'])?></p><table><?php foreach($items as $x):?><tr><td><?=e($x['item_name'])?><br><?=$x['qty']?> x <?=money($x['unit_price'])?></td><td class="right"><?=money($x['line_total'])?></td></tr><?php endforeach;?></table>
<p class="right">Subtotal: <?=money($sale['subtotal'])?><br>Discount: <?=money($sale['discount'])?><br><span class="total">TOTAL: <?=money($sale['total'])?></span><br>Paid: <?=money($sale['amount_paid'])?><br>Balance: <?=money($sale['balance'])?></p>
<div class="center"><hr><?=e($set['receipt_footer'])?><br><br><button onclick="window.print()">PRINT</button></div></body></html>